INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Hat jedes Subnetz bei 192.168.1.0/24 mit /26 genau 64 Adressen?', 2, '[{"text": "Ja", "correct": true, "because": "2^(32-26) = 64"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele nutzbare Hosts hat ein /27-Subnetz?', 3, '[{"text": "30", "correct": true, "because": "2^(32-27) - 2 = 30"}, {"text": "32", "correct": false, "because": "Ohne Abzug"}, {"text": "28", "correct": false, "because": "Falsche Subtraktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 192.168.1.0/25 hat 128 Adressen. b) Es hat 126 Hosts.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) 2^7 = 128, b) 128 - 2 = 126"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei den Ergebnissen von 192.168.1.0/24 mit /26?', 4, '[{"text": "Adressbereiche", "correct": false, "because": "Definiert Subnetze"}, {"text": "Hostanzahl", "correct": false, "because": "Bestimmt Nutzung"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das erste Subnetz von 192.168.1.0/26 den Bereich 192.168.1.0-63 hat?', 2, '[{"text": "Ja", "correct": true, "because": "Inkrement 64"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Adressbereich gehört zum zweiten Subnetz von 10.0.0.0/24 mit /25?', 3, '[{"text": "10.0.0.128-10.0.0.255", "correct": true, "because": "Inkrement 128"}, {"text": "10.0.0.64-10.0.0.127", "correct": false, "because": "Für /26"}, {"text": "10.0.0.0-10.0.0.127", "correct": false, "because": "Erstes Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse liefert 192.168.1.0/24 mit /27?', 5, '[{"text": "8 Subnetze", "correct": true, "because": "2^(27-24) = 8"}, {"text": "30 Hosts pro Subnetz", "correct": true, "because": "2^(32-27) - 2 = 30"}, {"text": "4 Subnetze", "correct": false, "because": "Für /26"}, {"text": "32 Adressen insgesamt", "correct": false, "because": "Pro Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 192.168.1.0/26 hat 62 Hosts pro Subnetz. b) Es hat 2 Subnetze. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2^(26-24) = 4 Subnetze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Ergebnisse von 192.168.1.0/24?', 4, '[{"text": "Inkrement", "correct": false, "because": "Bestimmt Bereiche"}, {"text": "Subnetzmaske", "correct": false, "because": "Definiert Aufteilung"}, {"text": "Betriebssystem", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat 192.168.1.0/24 mit /30 64 Subnetze?', 2, '[{"text": "Ja", "correct": true, "because": "2^(30-24) = 64"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich ist das dritte Subnetz von 172.16.0.0/24 mit /26?', 4, '[{"text": "172.16.0.128-172.16.0.191", "correct": true, "because": "Inkrement 64, 3. Subnetz"}, {"text": "172.16.0.64-172.16.0.127", "correct": false, "because": "2. Subnetz"}, {"text": "172.16.0.192-172.16.0.255", "correct": false, "because": "4. Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 192.168.1.0/25 nur 64 Adressen hat. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "2^7 = 128 Adressen"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei den Ergebnissen?', 3, '[{"text": "Korrekte Bereiche", "correct": true, "because": "Definiert Subnetze"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 192.168.1.0/24 mit /28 hat 16 Subnetze. b) Jedes hat 14 Hosts.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) 2^(28-24) = 16, b) 2^(32-28) - 2 = 14"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse hat 10.0.0.0/24 mit /26?', 5, '[{"text": "4 Subnetze", "correct": true, "because": "2^(26-24) = 4"}, {"text": "62 Hosts pro Subnetz", "correct": true, "because": "2^(32-26) - 2 = 62"}, {"text": "2 Subnetze", "correct": false, "because": "Für /25"}, {"text": "64 Adressen insgesamt", "correct": false, "because": "Pro Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei den Ergebnissen unwichtig?', 3, '[{"text": "Adressbereiche", "correct": false, "because": "Definiert Subnetze"}, {"text": "Hostanzahl", "correct": false, "because": "Bestimmt Nutzung"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat das vierte Subnetz von 192.168.1.0/24 mit /26 den Bereich 192.168.1.192-255?', 3, '[{"text": "Ja", "correct": true, "because": "Inkrement 64, 4. Subnetz"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 192.168.1.0/24 mit /29 32 Subnetze hat?', 2, '[{"text": "Ja", "correct": true, "because": "2^(29-24) = 32"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich gehört zum ersten Subnetz von 172.16.0.0/23 mit /25?', 4, '[{"text": "172.16.0.0-172.16.0.127", "correct": true, "because": "Inkrement 128"}, {"text": "172.16.0.128-172.16.0.255", "correct": false, "because": "2. Subnetz"}, {"text": "172.16.0.0-172.16.0.63", "correct": false, "because": "Für /26"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Hosts hat jedes Subnetz bei 10.0.0.0/24 mit /30?', 3, '[{"text": "2", "correct": true, "because": "2^(32-30) - 2 = 2"}, {"text": "4", "correct": false, "because": "Ohne Abzug"}, {"text": "6", "correct": false, "because": "Für /29"}]');
